struct cmp_ctx { const char *field; int dir; };

static int cmp(const void *a, const void *b, void *opaque) {
    struct cmp_ctx *c = opaque;                       /* the environment */
    return (c->dir * strcmp(((const row *)a)->key, ((const row *)b)->key));
}

/* the creator: allocates the environment once */
struct cmp_ctx env = { .field = "deadline", .dir = 1 };
qsort_r(rows, n, sizeof *rows, cmp, &env);
